CONFIG.applyTheme = function () {
  const root = document.documentElement;
  Object.entries(this.theme).forEach(([key, val]) => {
    root.style.setProperty(key, val);
  });
};

CONFIG.applyLogo = function (containerId) {
  const container = document.getElementById(containerId || 'logoIcon');
  if (!container) return;
  const size = this.logo.size || 40;
  if (this.logo.type === 'image' && this.logo.img) {
    container.innerHTML = `<img src="${this.logo.img}" alt="${this.logo.alt}" style="width:${size}px;height:${size}px">`;
  } else {
    container.innerHTML = this.logo.svg;
  }
  const el = container.firstElementChild;
  if (el) {
    el.style.width = size + 'px';
    el.style.height = size + 'px';
  }
};

CONFIG.applyFavicon = function () {
  const link = document.getElementById('favicon');
  if (!link) return;
  if (this.favicon.type === 'custom' && this.favicon.href) {
    const href = this.favicon.href;
    link.href = href;
    link.type = href.endsWith('.svg') ? 'image/svg+xml' : 'image/x-icon';
  } else {
    const svg = (this.logo.svg || '').replace(/<\?xml.*?\?>/, '').trim();
    link.href = 'data:image/svg+xml,' + encodeURIComponent(svg);
    link.type = 'image/svg+xml';
  }
};
